// Section: wire_class

class AlighieriWire implements BaseWire {
  factory AlighieriWire.fromExternalLibrary(ExternalLibrary lib) =>
      AlighieriWire(lib.ffiDynamicLibrary);

  /// Holds the symbol lookup function.
  final ffi.Pointer<T> Function<T extends ffi.NativeType>(String symbolName)
  _lookup;

  /// The symbols are looked up in [dynamicLibrary].
  AlighieriWire(ffi.DynamicLibrary dynamicLibrary)
    : _lookup = dynamicLibrary.lookup;
}
